package com.airesumebuilder.feature.audit.entity;
import com.airesumebuilder.feature.auth.entity.User; import jakarta.persistence.*; import java.time.Instant; import lombok.*;
@Entity @Table(name="audit_logs") @Getter @Setter @NoArgsConstructor
public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(name="entity_type",nullable=false,length=100) private String entityType; @Column(name="entity_id",nullable=false) private Long entityId; @Column(nullable=false,length=100) private String action; @Column(name="before_state",columnDefinition="jsonb") private String beforeState; @Column(name="after_state",columnDefinition="jsonb") private String afterState; @Column(name="ip_address",length=45) private String ipAddress; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();} }
